class Profile {
  final String id, fullName, role, status;
  final String? email, phone, avatarUrl;

  Profile({required this.id, required this.fullName, required this.role, required this.status, this.email, this.phone, this.avatarUrl});

  bool get isDriver => role == 'driver';
  bool get isPassenger => role == 'passenger';
  bool get hasAvatar => avatarUrl != null && avatarUrl!.trim().isNotEmpty;

  /// First letter of the name — avatar fallback when no image is set.
  /// Takes a whole code point so surrogate pairs are not split.
  String get initial {
    final n = fullName.trim();
    return n.isEmpty ? '?' : String.fromCharCode(n.runes.first);
  }

  /// `avatarUrl` is nullable-by-design, so removal uses [clearAvatar] instead of passing null.
  Profile copyWith({String? fullName, String? email, String? phone, String? avatarUrl, bool clearAvatar = false}) => Profile(
        id: id,
        fullName: fullName ?? this.fullName,
        role: role,
        status: status,
        email: email ?? this.email,
        phone: phone ?? this.phone,
        avatarUrl: clearAvatar ? null : (avatarUrl ?? this.avatarUrl),
      );

  factory Profile.fromMap(Map<String, dynamic> m) => Profile(
        id: m['id'],
        fullName: m['full_name'] ?? '',
        role: m['role'] ?? 'passenger',
        status: m['status'] ?? 'active',
        email: m['email'],
        phone: m['phone'],
        avatarUrl: m['avatar_url'],
      );

  @override
  bool operator ==(Object other) =>
      other is Profile &&
      other.id == id &&
      other.fullName == fullName &&
      other.role == role &&
      other.status == status &&
      other.email == email &&
      other.phone == phone &&
      other.avatarUrl == avatarUrl;

  @override
  int get hashCode => Object.hash(id, fullName, role, status, email, phone, avatarUrl);
}
